BUSINESS_HTML=r'''<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Panther Peptides Command Center</title><style>:root{--bg:#050b13;--p:#0d1b2d;--line:#294765;--t:#f2f7ff;--m:#93abc3;--g:#35d39a;--r:#ff7185;--a:#f0b64b}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 50% -15%,#183a61,#07111f 40%,#040910);color:var(--t);font:15px system-ui;min-height:100vh}.w{max-width:1500px;margin:auto;padding:18px}.top,.row,.actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.top{justify-content:space-between}.logo{width:48px;height:48px;border-radius:14px;background:linear-gradient(135deg,#4b9dff,#53dfc0);display:grid;place-items:center;color:#05101d;font-weight:900}h1,h2{margin:0}.muted{color:var(--m)}.card{background:linear-gradient(180deg,#102138,#091626);border:1px solid var(--line);border-radius:18px;padding:18px}.btn{border:1px solid #315779;background:#10243d;color:white;padding:11px 14px;border-radius:11px;font-weight:750;cursor:pointer}.primary{background:#174d8b}.yes{background:#123d32}.no{background:#431b25}.field{width:100%;background:#06111f;border:1px solid #315779;color:white;border-radius:11px;padding:13px}.strategy{display:grid;grid-template-columns:1fr auto;gap:10px;margin:15px 0}.metrics{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin:15px 0}.metric b{display:block;font-size:25px}.grid{display:grid;grid-template-columns:1.4fr .8fr;gap:15px}.event{border:1px solid #203b57;border-radius:12px;padding:11px;margin-top:8px;background:#081522}.pill{display:inline-block;border:1px solid #365a7c;border-radius:999px;padding:5px 9px;font-size:12px}.online,.available,.completed{color:#bdf5df;border-color:#286b59}.retrying,.blocked{color:#ffabb8;border-color:#8c3448}.loading,.awaiting_approval{color:#ffdc91;border-color:#8a6723}.tabs{display:flex;gap:8px;margin:14px 0;overflow:auto}.tab.active{outline:2px solid #4b9dff}.hidden{display:none}.banner,.notice{margin:14px 0;padding:11px 14px;border-radius:12px}.banner{border:1px solid #285f51;background:#0d2923;color:#c8f5e4}.notice{border:1px solid #8a6723;background:#2a2110;color:#ffdc91}.approval{border:2px solid var(--a);margin:15px 0}.table{overflow:auto}table{width:100%;border-collapse:collapse;min-width:650px}th,td{padding:10px;border-bottom:1px solid #1d354e;text-align:left}.login{max-width:500px;margin:8vh auto}@media(max-width:850px){.w{padding:10px}.top{align-items:flex-start}h1{font-size:31px}.metrics{grid-template-columns:repeat(2,1fr)}.grid,.strategy{grid-template-columns:1fr}.banner{font-size:13px}.btn{min-height:44px}}</style></head><body><div class="w"><header class="top"><div class="row"><div class="logo">PP</div><div><h1>Panther Peptides</h1><div class="muted">Jarvis Autonomous Business Command Center · <span id="ver">starting</span></div></div></div><div class="actions"><span id="state" class="pill loading">Starting…</span><button class="btn" onclick="load(true)">Refresh</button><a class="btn" href="/jarvis">Voice Console</a></div></header><div id="notice" class="notice hidden"></div><div id="login" class="card login hidden"><h2>Owner Access</h2><p class="muted">Authenticate to load the business dashboard.</p><p><input id="pw" class="field" type="password" placeholder="Owner password" onkeydown="if(event.key==='Enter')login()"></p><button class="btn primary" onclick="login()">Open Jarvis</button><p id="err"></p></div><main id="app" class="hidden"><div class="banner">FOR RESEARCH USE ONLY — NOT FOR HUMAN OR VETERINARY USE · Jarvis may plan and execute available business actions autonomously. Owner decisions are presented one at a time.</div><section id="approval" class="card approval hidden"><div class="muted">JARVIS NEEDS ONE DECISION</div><h2 id="aqtitle"></h2><p id="aquestion"></p><div id="arationale" class="muted"></div><p id="acost"></p><div class="actions"><button class="btn yes" onclick="decide(true)">✓ APPROVE</button><button class="btn no" onclick="decide(false)">✕ DENY</button></div></section><div class="strategy"><input id="objective" class="field" placeholder="Give Jarvis a business objective" onkeydown="if(event.key==='Enter')runObjective()"><button class="btn primary" onclick="runObjective()">Run Autonomously</button></div><div class="metrics"><div class="card metric"><span class="muted">Available units</span><b id="avail">—</b></div><div class="card metric"><span class="muted">Held / quarantine</span><b id="held">—</b></div><div class="card metric"><span class="muted">Active objectives</span><b id="active">—</b></div><div class="card metric"><span class="muted">Awaiting approval</span><b id="waiting">—</b></div><div class="card metric"><span class="muted">Knowledge files</span><b id="knowledge">—</b></div></div><div class="tabs"><button class="btn tab active" onclick="tab('ops',this)">Strategy & Operations</button><button class="btn tab" onclick="tab('inv',this)">Available Inventory</button><button class="btn tab" onclick="tab('know',this)">Knowledge</button></div><section id="ops" class="grid"><div class="card"><h2>Jarvis Objectives</h2><div id="objectives"></div></div><div class="card"><h2>Recent Activity</h2><div id="events"></div></div></section><section id="inv" class="card hidden"><h2>Available Inventory</h2><p class="muted">Held and quarantined lots are hidden from this operating view.</p><div class="table"><table><thead><tr><th>Product</th><th>Lot</th><th>Qty</th><th>Docs</th></tr></thead><tbody id="inventory"></tbody></table></div></section><section id="know" class="card hidden"><h2>Jarvis Knowledge</h2><p class="muted">Upload operating references, SOPs, product and supplier information, PDFs, CSVs, Markdown and text.</p><form onsubmit="uploadKnowledge(event)"><input id="kf" class="field" type="file" required><p><input id="kc" class="field" placeholder="Category"></p><p><input id="kt" class="field" placeholder="Tags"></p><button class="btn primary">Add Knowledge</button></form><p id="kstat" class="muted"></p></section></main></div><script>const $=x=>document.getElementById(x);let D=null,A=null,busy=false;function setState(t,c){$('state').textContent=t;$('state').className='pill '+c}function note(t){$('notice').textContent=t;$('notice').classList.toggle('hidden',!t)}async function req(u,o={},ms=10000){let c=new AbortController(),timer=setTimeout(()=>c.abort(),ms);try{let r=await fetch(u,{...o,cache:'no-store',signal:c.signal}),d=await r.json().catch(()=>({}));if(!r.ok){let x=Error(d.detail||d.error||('HTTP '+r.status));x.status=r.status;throw x}return d}finally{clearTimeout(timer)}}function e(s){return String(s??'').replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]))}async function login(){try{await req('/auth/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({password:$('pw').value})});$('pw').value='';await load(true)}catch(x){$('err').textContent=x.message}}function tab(id,b){['ops','inv','know'].forEach(x=>$(x).classList.toggle('hidden',x!==id));document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));b.classList.add('active')}async function load(manual=false){if(busy&&!manual)return;busy=true;setState('Connecting…','loading');try{let b=await req('/client/bootstrap',{},7000);$('ver').textContent='v'+b.version;let rt=b.runtime||{};if(!b.authenticated){$('login').classList.remove('hidden');$('app').classList.add('hidden');note('');setState('Owner login required','loading');return}$('login').classList.add('hidden');$('app').classList.remove('hidden');setState(rt.worker_alive&&rt.watchdog_alive?'Jarvis online':'Jarvis runtime attention',rt.worker_alive?'online':'retrying');D=await req('/business/dashboard',{},12000);render();renderApproval(D.approval);note('');let r=D.runtime||{};setState(r.worker_alive&&r.watchdog_alive?'Jarvis online':'Jarvis runtime attention',r.worker_alive?'online':'retrying')}catch(x){if(x.status===401){$('login').classList.remove('hidden');$('app').classList.add('hidden');setState('Owner login required','loading')}else{setState('Retrying…','retrying');note('Dashboard connection problem: '+(x.name==='AbortError'?'request timed out':x.message)+'. Jarvis will retry automatically.');$('app').classList.remove('hidden')}}finally{busy=false}}function render(){let s=D.summary||{},r=D.runtime||{};$('avail').textContent=s.released_units??0;$('held').textContent=s.quarantined_units??0;$('active').textContent=(r.queued||0)+(r.running||0);$('waiting').textContent=r.awaiting_approval||0;$('knowledge').textContent=(D.knowledge||{}).files||0;$('objectives').innerHTML=(D.objectives||[]).slice(0,15).map(x=>`<div class="event"><b>#${x.id} ${e(x.title)}</b><div><span class="pill ${e(x.state)}">${e(x.state)}</span> step ${x.step}/${x.max_steps}</div>${x.blocked_reason?`<div class="muted">${e(x.blocked_reason)}</div>`:''}</div>`).join('')||'<p class="muted">No objectives yet.</p>';$('events').innerHTML=(D.events||[]).slice(0,10).map(x=>`<div class="event"><b>${e(x.title)}</b><div class="muted">${e(x.detail||'')}</div></div>`).join('')||'<p class="muted">No recent activity.</p>';let inv=(D.inventory||[]).filter(x=>['available','released','active'].includes(String(x.status).toLowerCase()));$('inventory').innerHTML=inv.map(x=>`<tr><td><b>${e(x.product)}</b></td><td>${e(x.lot_code||'—')}</td><td>${e(x.quantity)}</td><td>${e(x.coa_status||'unknown')}</td></tr>`).join('')||'<tr><td colspan="4" class="muted">No available inventory.</td></tr>';let k=D.knowledge||{};$('kstat').textContent=`${k.files||0} files · ${Number(k.characters||0).toLocaleString()} indexed characters`}function renderApproval(a){A=a;$('approval').classList.toggle('hidden',!a);if(!a)return;let p=a.payload||{};$('aqtitle').textContent=a.objective_title||'Owner decision';$('aquestion').textContent=p.question||a.action;$('arationale').textContent=p.rationale||'';$('acost').textContent=p.estimated_cost!=null?`Estimated cost: $${Number(p.estimated_cost).toFixed(2)}`:''}async function decide(ok){if(!A)return;await req('/agent/approval/'+A.id,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({approved:ok})});A=null;load(true)}async function runObjective(){let t=$('objective').value.trim();if(!t)return;$('objective').value='';try{let d=await req('/agent/v223/command',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({text:t,request_id:crypto.randomUUID()})},15000);note(d.message||'Objective queued.');setTimeout(()=>load(true),500)}catch(x){note('Could not queue objective: '+x.message)}}async function uploadKnowledge(ev){ev.preventDefault();let f=new FormData();f.append('file',$('kf').files[0]);f.append('category',$('kc').value||'general');f.append('tags',$('kt').value||'');try{await req('/knowledge/upload',{method:'POST',body:f},30000);ev.target.reset();load(true)}catch(x){note('Knowledge upload failed: '+x.message)}}load(true);setInterval(()=>load(false),5000)</script></body></html>'''